let t_bound_shape_task gs ~version ~expl t =
  assert (is_bound_sum_shape_version version);
  let current_shape = ref [] in
  Buffer.clear Shape.shape_buffer;
  let pr = Ident.create_ident_printer [] in
  let c = ref (-1) in
  let m = ref Ident.Mid.empty in
  (* All declarations shape *)
  let local_decls =
    let ut = Task.used_symbols (Task.used_theories t) in
    Task.local_decls t ut in
  let open Decl in
  let do_d d =
    match d.d_node with
    | Dparam _ls -> ()
    | Dprop (_, _pr, f) ->
        let sh =
          (try Shape.t_shape ~version pr c m f with Shape.ShapeTooLong -> ());
          Buffer.contents Shape.shape_buffer in
        Buffer.clear Shape.shape_buffer;
        add_and_prepend gs current_shape sh
    | _ -> () in
  List.iter do_d local_decls;
  (* TODO don't save empty shapes as \n as it could be confused with end of assignments *)
  let expl = if expl = "" then "empty_shape" else expl in
  add_and_prepend gs current_shape expl;
  (* The order should be [|shape|] :: [|goal|] :: [|rest of decl|] *)
  !current_shape

let save_session_and_exit c signum =
  (* Ignore all SIGINT, SIGHUP and SIGTERM, which may be received when
     gnatprove is called in GNATStudio, so that the session file is always
     saved. Wrap in exception block as some signals are not supported on
     windows. *)
  begin try
    Sys.set_signal Sys.sigint Sys.Signal_ignore;
    Sys.set_signal Sys.sighup Sys.Signal_ignore;
    Sys.set_signal Sys.sigterm Sys.Signal_ignore;
  with Invalid_argument _ -> () end;
  C.save_session c;
  exit signum

module Hstr = Exthtbl.Make(struct
  type t    = String.t
  let hash  = (Hashtbl.hash : string -> int)
  let equal = ((=) : string -> string -> bool)
end)

type ('a, 'b) t =
  { mutable size: int;                        (* number of entries *)
    mutable data: ('a, 'b) bucketlist array;  (* the buckets *)
    seed: int;                        (* for randomization *)
    mutable initial_size: int;                (* initial array size *)
  }

and ('a, 'b) bucketlist =
    Empty
  | Cons of { mutable key: 'a;
              mutable data: 'b;
              mutable next: ('a, 'b) bucketlist }

(* The sign of initial_size encodes the fact that a traversal is
   ongoing or not.

   This disables the efficient in place implementation of resizing.
*)

let ongoing_traversal h =
  Obj.size (Obj.repr h) < 4 (* compatibility with old hash tables *)
  || h.initial_size < 0

let flip_ongoing_traversal h =
  h.initial_size <- - h.initial_size

  if x >= n then x
  else if x * 2 > Sys.max_array_length then x
  else power_2_above (x * 2) n

let create ?(random = !randomized) initial_size =
  let s = power_2_above 16 initial_size in
  let seed = if random then Random.State.bits (Lazy.force prng) else 0 in
  { initial_size = s; size = 0; seed = seed; data = Array.make s Empty }

